const PHOTO_ID='photo-walk';
const PUBLIC_ORIGIN='https://campus-t-kolin-demo.lacyalbatross5.chatgpt.site';
const photoEvent={id:PHOTO_ID,title:'LUMA 光迹 · 把校园拍成明信片',brand:'LUMA PHOTO CLUB',category:'音乐艺术',school:'浙江大学',date:'12.12',time:'14:00 – 17:00',location:'紫金港校区 · 启真湖草坪',theme:'photo',poster:'CHASE THE LIGHT.<br>KEEP THE MOMENT.',caption:'LUMA × CAMPUS T / PHOTO WALK',shape:'◎',reward:'token',amount:0,capacity:120,joined:36,description:'带上手机或相机，跟随 LUMA 光迹一起发现校园里的光。沿着启真湖完成一段摄影漫游，拍下你眼中的校园明信片。现场扫描参与码报名签到，结束时扫描签退码，即可领取 100 积分和「光迹取景框」限定头像框。品牌与活动均为演示设定。'};
seed.unshift(photoEvent);
products.push({id:'photo-frame',name:'光迹取景框 · 摄影限定',brand:'LUMA PHOTO CLUB',category:'活动奖励',cost:0,stock:999,symbol:'◎',color:'sage',type:'frame',eventOnly:true,detail:'仅通过完成 LUMA 校园摄影活动的签到与签退获得，不在商城出售。'});
social.attendance??={};
let cameraStream=null,cameraFrame=0,cameraGeneration=0,cameraStarting=false,photoScanAction=null;
const actionURL=action=>PUBLIC_ORIGIN+'/#attend/'+PHOTO_ID+'/'+action;
function photoProgress(){return state.progress[PHOTO_ID];}
function onsiteHeader(label){$('#breadcrumb').textContent=label;document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page||(page==='attend'&&b.dataset.page==='scan')));}
function renderOnsite(){
 stopCamera();
 if(page==='scan'){onsiteHeader('扫一扫');$('#content').innerHTML=scannerView();return true;}
 if(page==='codes'){onsiteHeader('活动二维码');$('#content').innerHTML=codesView();return true;}
 if(page==='attend'){onsiteHeader('现场打卡');$('#content').innerHTML=attendanceView();return true;}
 return false;
}
function addOnsiteEntry(){
 if(page==='explore')$('#content').insertAdjacentHTML('afterbegin',`<div class="onsite-entry"><span class="scan-small">⌗</span><div><strong>已经到活动现场？</strong><p>扫一扫参与活动，记录你的校园足迹。</p></div><button class="primary" data-page="scan">扫一扫</button></div>`);
 if(page==='brand')$('#content').insertAdjacentHTML('afterbegin',`<div class="onsite-entry"><span class="scan-small">◎</span><div><strong>LUMA 校园摄影活动已就绪</strong><p>参与码、签退码与头像框奖励已配齐。</p></div><button class="primary" data-page="codes">现场物料</button></div>`);
}
function scannerView(){return heading('扫一扫，让相遇发生。','对准现场二维码，报名、签到或完成活动签退。')+`<div class="scanner-layout"><section class="scan-panel"><div class="camera-window"><video id="scan-video" muted playsinline aria-label="二维码摄像头预览"></video><div class="scan-reticle"><i></i><i></i><i></i><i></i><span id="camera-placeholder">⌗</span></div><div class="camera-caption" id="camera-status" role="status">点击下方按钮开启相机</div></div><div class="scan-controls"><button class="primary" id="start-camera">开启相机扫码</button><button class="outline" id="stop-camera" hidden>关闭相机</button><label class="outline album-button" tabindex="0" role="button">从相册识别<input id="qr-file" type="file" accept="image/*" hidden></label></div><p class="scan-hint">相机画面与相册图片仅在设备上识别，不上传。若内置浏览器无法打开相机，可使用相册或粘贴链接。</p><form id="scan-link-form"><label>也可以粘贴活动二维码中的链接<input name="url" type="text" required placeholder="https://…/#attend/photo-walk/checkin" autocomplete="off"></label><button class="outline full" type="submit">识别活动链接</button></form></section><aside class="scan-aside"><div class="panel photo-feature"><span class="eyebrow">LUMA × CAMPUS T</span><div class="mini-camera" aria-hidden="true">◎</div><h2>把校园拍成明信片</h2><p>12 月 12 日 · 浙江大学<br>用镜头收集光，也认识新的同好。</p><button class="primary full" data-event="photo-walk">查看摄影活动</button></div><div class="panel"><h3>现场参与路线</h3><ol class="scan-steps"><li>扫参与码：报名并签到</li><li>一起完成校园摄影漫游</li><li>扫签退码：领取积分与头像框</li></ol><p class="muted">演示记录保存在当前浏览器，请在同一浏览器完成签到与签退。</p><button class="text-button" data-page="codes">查看演示二维码物料</button></div></aside></div>`;}
function stopCamera(){cameraGeneration++;cameraStarting=false;cancelAnimationFrame(cameraFrame);cameraFrame=0;if(cameraStream)cameraStream.getTracks().forEach(t=>t.stop());cameraStream=null;const video=$('#scan-video');if(video)video.srcObject=null;}
function cameraStatus(message){const status=$('#camera-status');if(status)status.textContent=message;}
async function startCamera(){
 if(cameraStarting||cameraStream)return;
 if(!navigator.mediaDevices?.getUserMedia){cameraStatus('当前环境不支持相机，请从相册选择二维码或粘贴链接。');return;}
 const generation=++cameraGeneration;cameraStarting=true;cameraStatus('正在请求相机权限…');$('#start-camera').disabled=true;
 try{const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}},audio:false});
 if(generation!==cameraGeneration||page!=='scan'){stream.getTracks().forEach(t=>t.stop());return;}
 cameraStream=stream;cameraStarting=false;const video=$('#scan-video');video.srcObject=stream;await video.play();if(generation!==cameraGeneration)return;
 $('#camera-placeholder').hidden=true;$('#start-camera').hidden=true;$('#stop-camera').hidden=false;cameraStatus('将现场二维码放入框内');
 const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d',{willReadFrequently:true});let last=0;
 const tick=now=>{if(generation!==cameraGeneration||!cameraStream||page!=='scan')return;if(now-last>180&&video.readyState>=2){last=now;const scale=Math.min(1,960/video.videoWidth);canvas.width=Math.round(video.videoWidth*scale);canvas.height=Math.round(video.videoHeight*scale);ctx.drawImage(video,0,0,canvas.width,canvas.height);const pixels=ctx.getImageData(0,0,canvas.width,canvas.height);const code=jsQR(pixels.data,pixels.width,pixels.height,{inversionAttempts:'attemptBoth'});if(code){const parsed=parseActivityCode(code.data);if(parsed){showAttendance(parsed);return;}cameraStatus('这不是 CampusT 支持的活动码，请换一个二维码。');}}
 cameraFrame=requestAnimationFrame(tick);};cameraFrame=requestAnimationFrame(tick);
 }catch(error){if(generation!==cameraGeneration)return;stopCamera();const messages={NotAllowedError:'相机权限未开启，可在浏览器设置中允许，或使用相册识别。',NotFoundError:'未检测到相机，请使用相册识别或粘贴链接。',NotReadableError:'相机正被占用，请关闭其他使用相机的应用。'};cameraStatus(messages[error.name]||'相机暂时无法使用，请使用相册或粘贴链接。');if($('#start-camera')){$('#start-camera').disabled=false;$('#start-camera').hidden=false;}}
}
function parseActivityCode(raw){try{const u=new URL(raw);if(u.origin!==PUBLIC_ORIGIN||u.pathname!=='/'||u.search||u.username||u.password)return null;const match=u.hash.match(/^#attend\/photo-walk\/(checkin|checkout)$/);return match?match[1]:null;}catch{return null;}}
function showAttendance(action){stopCamera();photoScanAction=action;page='attend';history.replaceState(null,'','#attend/'+PHOTO_ID+'/'+action);document.querySelectorAll('dialog[open]').forEach(d=>d.close());render();window.scrollTo({top:0,behavior:'smooth'});}
function attendanceView(){const progress=photoProgress(),out=photoScanAction==='checkout',complete=progress==='claimed',checked=progress==='checked';const blocked=out&&!checked&&!complete;return `<div class="attendance-page"><button class="text-button" data-page="scan">返回扫一扫</button><div class="attendance-card"><div class="attendance-brand">LUMA × CAMPUS T <span>${out?'签退码':'参与码'}</span></div><div class="attendance-icon">${complete?'✓':out?'✧':'◎'}</div><h1>${complete?'这段校园时光，已收藏':out?'为今天的摄影漫游画个句号':'欢迎加入校园摄影漫游'}</h1><h2>把校园拍成明信片</h2><p>12 月 12 日 14:00–17:00<br>浙江大学 · 紫金港校区 · 启真湖草坪</p><div class="onsite-reward"><span class="reward-avatar">K<img src="assets/photo-frame.svg" alt="光迹取景框头像框"></span><div><strong>100 积分 + 光迹限定头像框</strong><small>完成签到和签退后自动到账</small></div></div>${blocked?'<div class="info-banner">还没有签到记录。请先扫描现场参与码完成签到，再进行签退。</div>':complete?'<div class="info-banner">奖励已领取，无需重复签到或签退。</div>':checked&&!out?'<div class="info-banner">你已签到。活动结束后，扫描签退码领取奖励。</div>':''}<button class="primary full" id="attendance-confirm" ${blocked||complete||(checked&&!out)?'disabled':''}>${complete?'活动已完成':out?'确认签退并领取奖励':checked?'已签到':progress==='joined'?'确认现场签到':'报名并现场签到'}</button>${complete?'<button class="outline full" data-mine-tab="dress">查看并穿戴头像框</button>':blocked?'<button class="outline full" data-page="scan">去扫描参与码</button>':'<button class="text-button" data-event="photo-walk">查看活动详情</button>'}<p class="form-note">本活动为演示体验，支持提前打卡；记录仅保存在当前浏览器，不作为真实到场证明。</p></div></div>`;}
function confirmAttendance(action){const progress=photoProgress();if(!state.wallet)return 'wallet';if(progress==='claimed')return 'complete';if(action==='checkin'){if(progress==='checked')return 'checked';if(!progress&&photoEvent.joined>=photoEvent.capacity)return 'full';state.progress[PHOTO_ID]='checked';social.attendance[PHOTO_ID]={...social.attendance[PHOTO_ID],checkin:new Date().toISOString()};save();return 'checked';}if(action==='checkout'){if(progress!=='checked')return 'needs-checkin';grantEventPoints(photoEvent);if(!social.owned.includes('photo-frame'))social.owned.push('photo-frame');social.attendance[PHOTO_ID]={...social.attendance[PHOTO_ID],checkout:new Date().toISOString()};state.progress[PHOTO_ID]='claimed';save();return 'complete';}return 'invalid';}
function showPhotoDetail(){activeEvent=PHOTO_ID;const p=photoProgress();const checked=p==='checked'||p==='claimed',complete=p==='claimed';const record=social.attendance[PHOTO_ID];$('#detail').innerHTML=`<button class="icon-button" data-close aria-label="关闭">✕</button>${poster(photoEvent)}<div class="detail-body"><span class="eyebrow">LUMA × CAMPUS T / PHOTO WALK</span><h2>${photoEvent.title}</h2><div class="card-meta"><span>${icon('pin')}${photoEvent.location}</span><span>${icon('calendar')}12.12 · 14:00–17:00</span></div><p class="description">${photoEvent.description}</p><div class="onsite-reward"><span class="reward-avatar">K<img src="assets/photo-frame.svg" alt="摄影活动限定头像框"></span><div><strong>光迹取景框 · 活动限定</strong><small>完成签到与签退，获得头像框与 100 积分</small></div></div><div class="task-panel"><h3>现场参与进度</h3>${[['报名活动',!!p],['扫描参与码 · 完成签到',checked],['扫描签退码 · 领取奖励',complete]].map(([label,done],i)=>`<div class="task ${done?'done':''}"><span class="task-num">${done?'✓':i+1}</span><span>${label}</span><span>${done?'已完成':'待完成'}</span></div>`).join('')}</div>${record?`<p class="form-note">签到：${record.checkin?new Date(record.checkin).toLocaleString('zh-CN'):'未完成'}${record.checkout?'<br>签退：'+new Date(record.checkout).toLocaleString('zh-CN'):''}</p>`:''}<div class="photo-detail-actions">${!p?'<button class="primary" data-photo-register>报名参加</button>':''}${complete?'<button class="primary" data-photo-dress>穿戴活动头像框</button>':'<button class="primary" data-open-scanner>去扫一扫打卡</button>'}<button class="outline" data-photo-codes>查看活动二维码</button></div><p class="form-note">请在同一浏览器完成两次扫码。静态演示码不限制时间和位置。</p></div>`;if(!$('#detail').open)$('#detail').showModal();}
function codesView(){return heading('把相遇，放进一张二维码。','LUMA 校园摄影活动 · 可下载的现场物料',`<button class="outline" data-event="photo-walk">活动详情</button>`)+`<div class="qr-intro"><div><span class="eyebrow">LUMA × CAMPUS T</span><h2>把校园拍成明信片</h2><p>12 月 12 日 · 浙江大学启真湖草坪<br>将参与码放在入场处，将签退码放在离场处。</p></div><span class="reward-avatar big">K<img src="assets/photo-frame.svg" alt="光迹限定头像框"></span></div><div class="qr-grid">${[['checkin','参与二维码','扫码报名 + 现场签到'],['checkout','签退二维码','已签到后，扫码签退领取奖励']].map(([action,title,sub])=>`<article class="panel qr-card"><span class="qr-label">${action==='checkin'?'ARRIVAL / 现场参与':'FINISH / 活动签退'}</span><h2>${title}</h2><p>${sub}</p><img class="qr-image" src="assets/photo-${action}.png" alt="${title}"><div class="qr-downloads"><a class="primary" href="assets/photo-${action}.png" download>下载二维码 PNG</a><a class="outline" href="assets/photo-${action}-poster.svg" download>下载打印海报</a></div><button class="text-button" data-copy-code="${action}">复制活动链接</button><button class="text-button" data-test-code="${action}">体验此码</button></article>`).join('')}</div><div class="panel frame-download"><img src="assets/photo-frame.svg" alt="透明背景摄影头像框"><div><h3>光迹取景框 · 摄影限定奖励</h3><p>鼠尾草绿与暖金色镜头边框，完成活动后在「我的装扮」穿戴。</p><a class="outline" href="assets/photo-frame.svg" download>下载透明头像框 SVG</a></div></div><p class="form-note">二维码指向已公开的 CampusT 网站。仅用于体验；不包含身份、一次性签名或防转发校验。同一浏览器的奖励不会重复发放。</p>`;}
async function readQRFile(file){if(!file)return;stopCamera();render();cameraStatus('正在识别所选图片…');if(file.size>20*1024*1024){cameraStatus('图片超过 20 MB，请选择更小的图片。');return;}const generation=cameraGeneration;const url=URL.createObjectURL(file);try{const image=new Image();image.src=url;await image.decode();const scale=Math.min(1,1600/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(image,0,0,canvas.width,canvas.height);const pixels=ctx.getImageData(0,0,canvas.width,canvas.height),code=jsQR(pixels.data,pixels.width,pixels.height,{inversionAttempts:'attemptBoth'});if(generation!==cameraGeneration||page!=='scan')return;const action=code&&parseActivityCode(code.data);if(action)showAttendance(action);else cameraStatus(code?'该二维码不是支持的 CampusT 活动码。':'没有识别到二维码，请选择完整、清晰的二维码图片。');}catch{cameraStatus('无法读取这张图片，请使用 PNG 或 JPG 图片。');}finally{URL.revokeObjectURL(url);}}
function routeAttendance(){const match=location.hash.match(/^#attend\/photo-walk\/(checkin|checkout)$/);if(match){photoScanAction=match[1];page='attend';render();}}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(b.id==='start-camera')startCamera();if(b.id==='stop-camera'){stopCamera();render();}if('openScanner' in d){$('#detail').close();navigate('scan');}if('photoCodes' in d){$('#detail').close();navigate('codes');}if('photoDress' in d){$('#detail').close();mineTab='dress';navigate('me');}if('photoRegister' in d){if(!state.wallet){$('#wallet-dialog').showModal();return;}if(!photoProgress())state.progress[PHOTO_ID]='joined';save();render();showPhotoDetail();toast('报名成功，到达现场后扫描参与码签到');}if(b.id==='attendance-confirm'){const result=confirmAttendance(photoScanAction);if(result==='wallet'){$('#wallet-dialog').showModal();return;}render();toast(result==='complete'?'签退完成，积分与头像框已到账':result==='checked'?'签到成功，摄影漫游结束后记得扫码签退':'请先完成现场签到');}if(d.testCode)showAttendance(d.testCode);if(d.copyCode){try{await navigator.clipboard.writeText(actionURL(d.copyCode));toast('活动链接已复制');}catch{modal('复制活动链接',`<label>长按或选中下方链接复制<input readonly value="${actionURL(d.copyCode)}"></label>`);}}});
document.addEventListener('submit',e=>{if(e.target.id!=='scan-link-form')return;e.preventDefault();const raw=String(new FormData(e.target).get('url')||'').trim(),action=parseActivityCode(raw);if(action)showAttendance(action);else cameraStatus('链接无效，请粘贴本站的活动参与码或签退码链接。');});
document.addEventListener('change',e=>{if(e.target.id==='qr-file')readQRFile(e.target.files[0]);});
document.addEventListener('keydown',e=>{if(e.target.matches('.album-button')&&(e.key==='Enter'||e.key===' ')){e.preventDefault();$('#qr-file').click();}});
document.addEventListener('visibilitychange',()=>{if(document.hidden){stopCamera();if(page==='scan')render();}});
window.addEventListener('pagehide',stopCamera);window.addEventListener('hashchange',routeAttendance);
render();routeAttendance();
